import sys


def check(s):
    st = []
    for j, ch in enumerate(s, 1):
        if ch in '([{':
            st.append((ch, j))
        elif ch in ')]}':
            want = {')': '(', ']': '[', '}': '{'}[ch]
            if not st or st[-1][0] != want:
                return f"ERR {j}"
            st.pop()
    return f"ERR {st[0][1]}" if st else "OK"


def main():
    lines = sys.stdin.read().split('\n')
    q = int(lines[0])
    print('\n'.join(check(lines[1 + i] if 1 + i < len(lines) else '') for i in range(q)))


main()

