#include <iostream>
#include <string>
#include <vector>
using namespace std;

static string check(const string& s) {
    vector<pair<char, int>> st;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        int pos = (int)i + 1;
        if (c == '(' || c == '[' || c == '{') {
            st.push_back({c, pos});
        } else if (c == ')' || c == ']' || c == '}') {
            char want = c == ')' ? '(' : (c == ']' ? '[' : '{');
            if (st.empty() || st.back().first != want) return "ERR " + to_string(pos);
            st.pop_back();
        }
    }
    if (!st.empty()) return "ERR " + to_string(st[0].second);
    return "OK";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int q = stoi(line);
    while (q--) {
        if (!getline(cin, line)) line.clear();
        if (!line.empty() && line.back() == '\r') line.pop_back();
        cout << check(line) << '\n';
    }
    return 0;
}

